/* Simulated flights: stable quotes, participant snapshots, original-payer refunds. */
(function(root){'use strict';
const uidSafe=()=>typeof uid==='function'?uid():'flt-'+Date.now()+'-'+Math.random().toString(36).slice(2),account=()=>String(actId()||'main'),norm=v=>NorthHotelData.normalize(v),money=n=>'¥'+Number(n).toFixed(2);
let orderView=false,orderLimit=12,detailId=null,detailOrigin=null,liveSignature='';
function own(o){return o&&String(o.accountId||'main')===account();}
function deadline(o){const d=new Date(o.date+'T00:00:00');d.setDate(d.getDate()+1);return Math.max(Number.isFinite(+d)?+d:0,+o.arriveAt||0);}
function visible(o,now=Date.now()){if(!own(o))return false;if(o.status==='cancelled')return now<(+o.refundedAt||0)+86400000;return now<deadline(o);}
function rows(){return (tvInit().trips||[]).filter(o=>o.flightV2&&visible(o));}
function userRows(){return rows().filter(o=>!NorthHotelData.roleOrder(o));}
function current(x){const id=typeof x==='string'?x:x?.id;return (tvInit().trips||[]).find(o=>o.id===id&&own(o));}
function flightReady(){return typeof NorthTravelFlight!=='undefined'&&typeof NorthTravelFlight.state==='function';}
function quote(){const s=flightReady()?NorthTravelFlight.state():null;return s&&s.quote||null;}
function cname(k){return {economy:'经济舱',business:'公务舱',first:'头等舱'}[k]||'';}
function counts(q){return q.adults+'成人'+q.children+'儿童'+q.infants+'婴儿';}
function names(o){const a=(o.people||[]).map(p=>p.name);const rest=Math.max(0,o.adults-a.length);return a.join('、')+(rest?'、其他'+rest+'位成人':'')+(o.children?'，'+o.children+'位儿童':'')+(o.infants?'，'+o.infants+'位婴儿':'');}
function summary(x){const o=current(x);if(!o||!visible(o))return '机票订单已结束／已清理';return '模拟机票 '+o.from+'→'+o.to+' · '+o.date+' '+o.dep+'—'+o.arr+' · '+cname(o.cls)+' · '+counts(o)+' · 同行：'+names(o)+' · '+(o.people.length===1&&o.people[0].id==='me'&&o.adults===1&&!o.children&&!o.infants?'用户独自出游':o.people.some(p=>p.id==='me')?'用户与同行者出游':'角色自行出游')+' · '+NorthHotelData.payerLabel(o)+' '+money(o.price)+' · '+(o.status==='cancelled'?'已退款':'预订成功');}
function day(date,time){return new Date(date+'T'+time+':00').getTime();}
function hh(m){return String(Math.floor(m/60)%24).padStart(2,'0')+':'+String(m%60).padStart(2,'0');}
function seed(l){return [...l.from+'|'+l.to+'|'+l.date].reduce((n,c)=>(n*31+c.charCodeAt(0))>>>0,17);}
function total(q,adultCents){return adultCents*q.adults+Math.round(adultCents*.5)*q.children+Math.round(adultCents*.1)*q.infants;}
function flights(q,leg=q?.selectedLeg||0){const l=q?.legs?.[leg];if(!l)return [];const n=seed(l),intl=NorthTravelFlight.cityFallback(l.from)?.i||NorthTravelFlight.cityFallback(l.to)?.i,base=typeof tvPrice==='function'?tvPrice(l.from,l.to,q.cls):(intl?3800:560)*({economy:1,business:2.4,first:4.2}[q.cls]);return Array.from({length:6},(_,i)=>{const depMinutes=7*60+(n%5)*30+i*150,duration=(intl?420:100)+(n%4)*20+(i%3)*15,stop=i===4,mins=duration+(stop?80:0),dep=hh(depMinutes),arr=hh(depMinutes+mins),adultCents=Math.round((base*.75+(n%90)+i*35)/10)*1000,id=[l.from,l.to,l.date,q.cls,i].join('|');return {id,index:i,from:l.from,to:l.to,date:l.date,no:'SP'+(1000+n%7000+i),dep,arr,nd:depMinutes+mins>=1440,duration:mins,stop,large:i%2===0,bag:i!==2,shared:i%3===0,adultCents,totalCents:total(q,adultCents),departAt:day(l.date,dep),arriveAt:day(l.date,dep)+mins*60000};});}
function validate(q){if(!q||q.account!==account()||!Array.isArray(q.legs)||q.legs.length<1||q.legs.length>4||!cname(q.cls)||!['one','return','multi'].includes(q.type))return '查询条件已失效，请重新查询';if(!Array.isArray(q.people)||!q.people.length||q.people.length>9||new Set(q.people.map(p=>p.id)).size!==q.people.length)return '出行人员无效';if(q.people.some(p=>p.id!=='me'&&(!(p.id||'').startsWith('role:')||!getC(p.id.slice(5))||getC(p.id.slice(5)).deleted||getC(p.id.slice(5)).blocked||getC(p.id.slice(5)).isPhoneFriend)))return '同行角色已变化，请重新选择';if(![q.adults,q.children,q.infants].every(Number.isInteger)||q.adults<q.people.length||q.children<0||q.infants<0||q.adults+q.children+q.infants>9||q.infants>q.adults)return '人数无效';for(let i=0;i<q.legs.length;i++){const l=q.legs[i],d=new Date(l.date+'T12:00:00');if(!/^\d{4}-\d{2}-\d{2}$/.test(l.date||'')||!Number.isFinite(+d)||d.getFullYear()+'-'+String(d.getMonth()+1).padStart(2,'0')+'-'+String(d.getDate()).padStart(2,'0')!==l.date||l.date<todayStr()||i&&l.date<q.legs[i-1].date||!NorthTravelFlight.cityFallback(l.from)||!NorthTravelFlight.cityFallback(l.to)||norm(l.from)===norm(l.to))return '城市或日期无效';}return '';}
function startQuote(q){detailId=null;orderView=false;q.selectedLeg=0;q.sort='recommended';q.filters={};q.id=uidSafe();}
function scroll(){return document.querySelector('.ctf-flight-scroll')?.scrollTop||0;}
function redraw(top=scroll()){root.render();const apply=()=>{const e=document.querySelector('.ctf-flight-scroll');if(e)e.scrollTop=top;};if(typeof requestAnimationFrame==='function')requestAnimationFrame(apply);else apply();}
function setLeg(i){const q=quote();if(!q?.legs[i])return;q.selectedLeg=i;save();redraw(0);}
function sorted(q){const f=q.filters||{};let a=flights(q).filter(x=>(!f.afternoon||+x.dep.slice(0,2)>=12)&&(!f.large||x.large)&&(!f.bag||x.bag)&&(!f.noShared||!x.shared)&&(!f.direct||!x.stop)&&(!f.maxPrice||x.totalCents<=f.maxPrice*100));if(q.sort==='price')a.sort((a,b)=>a.totalCents-b.totalCents);else if(q.sort==='time')a.sort((a,b)=>a.departAt-b.departAt);else if(q.sort==='direct')a.sort((a,b)=>Number(a.stop)-Number(b.stop)||a.totalCents-b.totalCents);return a;}
function sort(k){const q=quote();if(!q||!['recommended','direct','time','price'].includes(k))return;q.sort=k;save();redraw();}
function toggle(k){if(!['afternoon','large','bag','noShared'].includes(k))return;const q=quote();q.filters=q.filters||{};q.filters[k]=!q.filters[k];save();redraw();}
function filter(){const q=quote(),f=q.filters||{};NorthTravelFlight.modal('<h3>筛选航班</h3><label><input id="ctfDirect" type="checkbox" '+(f.direct?'checked':'')+'>只看直飞</label><label>整组总价上限（元）<input id="ctfMaxPrice" type="number" min="0" step="1" value="'+(f.maxPrice||'')+'" placeholder="不限"></label><button onclick="NorthFlightBooking.saveFilter()">应用筛选</button><button onclick="NorthFlightBooking.clearFilter()">清除筛选</button>');}
function saveFilter(){const q=quote(),text=document.getElementById('ctfMaxPrice').value,v=text===''?0:Number(text);if(!Number.isFinite(v)||v<0||v>1000000)return toast('请输入有效价格上限');Object.assign(q.filters,{direct:document.getElementById('ctfDirect').checked,maxPrice:v});save();closeModal();redraw();}
function clearFilter(){quote().filters={};save();closeModal();redraw();}
function shiftDate(d){const q=quote(),i=q.selectedLeg||0;if(!q?.legs[i]||d<todayStr())return;const proposed={...q,legs:q.legs.map((l,j)=>({...l,date:j===i?d:l.date}))},error=validate(proposed);if(error)return toast(error);q.legs=proposed.legs;const s=NorthTravelFlight.state();if(s.type==='return'&&i===1)s.ret=d;else if(s.legs[i])s.legs[i].date=d;save();redraw(0);}
function datePicker(){const q=quote(),i=q.selectedLeg||0;NorthTravelFlight.modal('<h3>出行日期</h3><input id="ctfListDate" type="date" min="'+todayStr()+'" value="'+q.legs[i].date+'"><button onclick="NorthFlightBooking.useDate()">确定日期</button>');}
function useDate(){const d=document.getElementById('ctfListDate').value;shiftDate(d);closeModal();}
function key(q,f){return JSON.stringify([q.account,f.id,q.adults,q.children,q.infants,q.people.map(p=>p.id).sort()]);}
function existing(q,f,c=null){return rows().find(o=>NorthHotelData.roleOrder(o)===!!c&&(!c||o.cid===c.id)&&o.bookingKey===key(q,f)&&o.status==='upcoming');}
function readMoney(c){return typeof tvHotelRoleMoney==='function'?tvHotelRoleMoney(c):null;}
function applyRole(c,source,cents,item,o){const d=S.spy?.[c.id];let currentBalance;if(source==='roleWallet')currentBalance=c.wallet;else if(source==='roleBank'&&d)currentBalance=d.balance!=null?d.balance:(d.wallet||[]).reduce((n,x)=>n+Number(x.amount||0),0);else return false;const next=NorthHotelData.moneyNext(currentBalance,cents);if(next===null)return false;if(source==='roleWallet')c.wallet=next;else d.balance=next;if(d){d.wallet=d.wallet||[];d.wallet.unshift({item,amount:cents/100,when:o.date,tripId:o.id});d.wallet=d.wallet.slice(0,40);}return true;}
function applyUser(cents,note){const n=Math.round(Number(S.me.balance)*100);if(!Number.isSafeInteger(n)||n+cents<0)return false;if(typeof addBill==='function')addBill(cents<0?'out':'in',Math.abs(cents)/100,note);else{S.me.balance=(n+cents)/100;S.me.bills=S.me.bills||[];S.me.bills.push({id:uidSafe(),amount:Math.abs(cents)/100,type:cents<0?'out':'in',note,ts:Date.now()});}return true;}
function notify(o,refund=false){if(typeof msgs!=='function')return;const ids=[...new Set([...(o.people||[]).filter(p=>p.id.startsWith('role:')).map(p=>p.id.slice(5)),...(o.payer==='ta'?[o.cid]:[])])];for(const id of ids){const c=getC(id);if(!c||c.deleted||c.blocked)continue;const m={id:uidSafe(),time:Date.now(),role:o.payer==='ta'&&id===o.cid?'assistant':'user',type:'ticket',trip:{id:o.id,flightV2:true,accountId:o.accountId}};if(!refund)msgs(id).push(m);if(refund&&typeof scheduleReply==='function')scheduleReply(id,'[系统：你知情的模拟机票已退订，'+summary(o)+'。按人设自然回应，费用退回原付款方，不要当成仍有效。]');} }
function bookQuote(q,id,c=null,payment=null){const error=validate(q);if(error){toast(error);return false;}const f=flights(q).find(x=>x.id===id);if(!f||f.departAt<=Date.now()){toast('该航班已起飞或查询已失效');return false;}const prev=existing(q,f,c);if(prev)return true;const connected=rows().filter(o=>o.queryId===q.id&&o.status==='upcoming');if(connected.some(o=>(o.legIndex<(q.selectedLeg||0)&&o.arriveAt>f.departAt)||(o.legIndex>(q.selectedLeg||0)&&o.departAt<f.arriveAt))){toast('该航班与已订行程的时间冲突，请换一个航班或日期');return false;}const cents=f.totalCents;if(!Number.isSafeInteger(cents)||cents<=0)return false;if(c&&(c.deleted||c.blocked||c.isPhoneFriend))return false;const m=c?readMoney(c):null;if(c&&(!m)){toast('角色自己的银行余额不足');return false;}const participants=q.people.map(p=>({...p})),o={id:uidSafe(),accountId:account(),flightV2:true,bookingKey:key(q,f),queryId:q.id,legIndex:q.selectedLeg||0,journeyType:q.type,from:f.from,to:f.to,date:f.date,dep:f.dep,arr:f.arr,nd:f.nd,departAt:f.departAt,arriveAt:f.arriveAt,no:f.no,cls:q.cls,pax:q.adults+q.children+q.infants,adults:q.adults,children:q.children,infants:q.infants,people:participants,payer:c?'ta':'me',by:c?'ta':'me',cid:c?.id||participants.find(p=>p.id.startsWith('role:'))?.id.slice(5)||'',flier:participants.some(p=>p.id==='me')?'me':'ta',meet:false,price:cents/100,adultPrice:f.adultCents/100,status:'upcoming',ts:Date.now(),fundingSource:c?m.source:'userWallet',knownRoleIds:[...new Set([...participants.filter(p=>p.id.startsWith('role:')).map(p=>p.id.slice(5)),...(c?[c.id]:[])])],_hiddenFromChar:!c&&!participants.some(p=>p.id.startsWith('role:'))};if(payment?!NorthTravelPayment.charge(payment,cents,'机票：'+f.from+'→'+f.to,o):c?!applyRole(c,m.source,-cents,'机票预订：'+f.from+'→'+f.to,o):!applyUser(-cents,'机票：'+f.from+'→'+f.to)){toast('余额不足，未生成订单');return false;}const store=tvInit();store.trips=store.trips||[];store.trips.push(o);notify(o);save();if(typeof cur==='function'&&cur().p==='chat')root.render();return true;}
function book(id){const q=quote(),f=flights(q).find(x=>x.id===id);if(typeof NorthTravelPayment!=='undefined'&&f)return NorthTravelPayment.open({kind:'flight',quote:q,item:id,name:f.from+' → '+f.to+' · 机票',detail:f.date+' '+f.dep+'—'+f.arr,amount:f.totalCents/100});const top=scroll();if(bookQuote(quote(),id)){redraw(top);toast('模拟预订成功');}}
function refund(id){const o=current(id);if(!o||NorthHotelData.roleOrder(o)||o.status!=='upcoming'||o.flightV2&&(!visible(o)||o.departAt<=Date.now())||o.accountId&&o.accountId!==account())return false;const cents=Math.round(Number(o.price)*100);if(!Number.isSafeInteger(cents)||cents<=0)return false;let ok;if(o.paymentRequested)ok=NorthTravelPayment.refund(o);else if(o.payer==='ta'){const c=getC(o.cid);ok=c&&applyRole(c,o.fundingSource||'roleWallet',cents,'机票退款：'+o.from+'→'+o.to,o);}else ok=applyUser(cents,'机票退款：'+o.from+'→'+o.to);if(!ok){toast('无法确认原付款账户，订单未退订');return false;}o.status='cancelled';o.refundedAt=Date.now();notify(o,true);save();redraw();toast('已退订，费用原路返回');return true;}
function card(x){const o=current(x);if(!o||!visible(o))return '<div class="cth-chat-hotel cth-chat-unavailable">机票订单已结束／已清理</div>';return '<div class="cth-chat-hotel ctg-chat-ticket ctf-chat-flight" style="width:260px;max-width:100%" role="button" tabindex="0" data-order="'+esc(o.id)+'" onclick="event.stopPropagation();NorthFlightBooking.detail(this.dataset.order)" onkeydown="if(event.key===\'Enter\'||event.key===\' \'){event.preventDefault();NorthFlightBooking.detail(this.dataset.order)}"><div class="cth-chat-brand"><span>小鱼旅行 · 机票</span><small>模拟预订</small></div><div class="cth-chat-body"><div class="cth-chat-status">'+(o.status==='cancelled'?'已退款':'预订成功')+'</div><b class="cth-chat-name">'+esc(o.from)+' → '+esc(o.to)+'</b><p>'+o.date+' '+o.dep+'—'+o.arr+(o.nd?'（次日）':'')+' · '+esc(o.no)+'</p><p>'+cname(o.cls)+' · '+counts(o)+'</p><p>同行：'+esc(names(o))+'</p><div class="cth-chat-total"><span>'+esc(NorthHotelData.payerLabel(o))+'</span><strong>'+money(o.price)+'</strong></div></div><div class="cth-chat-footer"><span>整组乘客总价</span><b>查看详情 ›</b></div></div>';}
function detail(id){const o=current(id);if(!o||!visible(o))return toast('订单已结束／已清理');detailOrigin=typeof cur==='function'?{...cur()}:null;detailId=id;if(detailOrigin&&detailOrigin.p!=='travel'&&typeof go==='function')go('travel');NorthTravelFlight.showResults();}
function detailBack(){detailId=null;if(detailOrigin&&detailOrigin.p!=='travel'&&typeof back==='function'){detailOrigin=null;back();return;}detailOrigin=null;redraw();}
function detailPage(){const o=current(detailId);if(!o||!visible(o))return '<div class="ctf-app ctf-list-app"><header class="ctf-results-head"><button aria-label="返回上一页" onclick="NorthFlightBooking.detailBack()">‹</button><b>机票订单</b></header><main class="ctf-flight-scroll"><p class="ctf-flight-empty">订单已结束／已清理</p></main></div>';const payer=o.payer==='ta'?getC(o.cid):null,fields=[['出行日期',o.date],['航班',o.no+' · 小鱼航空'],['出发',o.from+' · '+o.dep],['抵达',o.to+' · '+o.arr+(o.nd?'（次日）':'')],['舱位',cname(o.cls)],['乘客人数',counts(o)],['出行人员',names(o)],['预订及付款方',NorthHotelData.payerLabel(o)],['订单金额',money(o.price)+'（整组总价）'],['订单号',o.id],['订单状态',o.status==='cancelled'?'已退款':'预订成功']];return '<div class="ctf-app ctf-list-app ctf-detail-app"><header class="ctf-results-head"><button aria-label="返回上一页" onclick="NorthFlightBooking.detailBack()">‹</button><b>机票订单详情</b></header><main class="ctf-flight-scroll"><section class="ctf-detail-ticket"><div class="ctf-detail-brand">'+NorthTravelHome.icon('dolphin')+'<b>小鱼旅行</b><span>模拟机票</span></div><div class="ctf-detail-status">'+(o.status==='cancelled'?'已退款':'预订成功')+'</div><div class="ctf-detail-route"><div><b>'+esc(o.from)+'</b><strong>'+o.dep+'</strong></div><i>→</i><div><b>'+esc(o.to)+'</b><strong>'+o.arr+(o.nd?'<small>次日</small>':'')+'</strong></div></div><p>'+o.date+' · '+esc(o.no)+' · '+cname(o.cls)+'</p></section><section class="ctf-detail-fields">'+fields.map(([k,v])=>'<div><span>'+esc(k)+'</span><b>'+esc(v)+'</b></div>').join('')+'</section><section class="ctf-detail-refund"><h3>退款与有效期</h3><p>退款金额退回原付款人的原账户，不改变付款方。退款后24小时自动隐藏。出行日期结束后隐藏，跨日航班保留至抵达；钱包账单保留。</p><p>儿童为成人价50%，婴儿为10%，以上均为小手机模拟票价。</p>'+(!NorthHotelData.roleOrder(o)&&o.status==='upcoming'&&o.departAt>Date.now()?'<button data-order="'+esc(o.id)+'" onclick="NorthFlightBooking.refund(this.dataset.order)">退订 · 原路退款</button>':'<b class="ctf-detail-refunded">'+(NorthHotelData.roleOrder(o)?'角色预订 · 仅可查看':o.status==='cancelled'?'已原路退款 '+money(o.price):'航班已出发，不能退订')+'</b>')+'</section></main></div>';}
function orders(){detailId=null;orderView=true;orderLimit=12;NorthTravelFlight.showResults();}
function dateButtons(q){const l=q.legs[q.selectedLeg||0],base=new Date(l.date+'T12:00:00');base.setDate(base.getDate()-2);const a=[];for(let i=0;i<5;i++){const d=new Date(base);d.setDate(d.getDate()+i);const s=d.getFullYear()+'-'+String(d.getMonth()+1).padStart(2,'0')+'-'+String(d.getDate()).padStart(2,'0');if(s<todayStr())continue;const clone={...q,legs:q.legs.map((x,j)=>({...x,date:j===(q.selectedLeg||0)?s:x.date}))},p=Math.min(...flights(clone).map(x=>x.totalCents))/100;a.push('<button class="'+(s===l.date?'selected':'')+'" data-date="'+s+'" onclick="NorthFlightBooking.shiftDate(this.dataset.date)"><small>'+(['日','一','二','三','四','五','六'][d.getDay()]?'周'+['日','一','二','三','四','五','六'][d.getDay()]:'')+'</small><b>'+s.slice(5)+'</b><span>¥'+Math.round(p)+'</span></button>');}return a.join('');}
function flightRow(q,f){const o=existing(q,f),expired=f.departAt<=Date.now();return '<article class="ctf-flight-row" data-flight="'+esc(f.id)+'"><div class="ctf-flight-line"><span class="ctf-fish">'+NorthTravelHome.icon('dolphin')+'</span><div class="ctf-time"><b>'+f.dep+'</b><span>'+esc(f.from)+'</span></div><div class="ctf-flight-path"><small>'+Math.floor(f.duration/60)+'小时'+f.duration%60+'分</small><i></i><small>'+(f.stop?'模拟中转':'模拟直飞')+'</small></div><div class="ctf-time"><b>'+f.arr+(f.nd?'<sup>+1</sup>':'')+'</b><span>'+esc(f.to)+'</span></div><div class="ctf-price"><b>¥'+String(f.totalCents/100)+'</b><small>整组总价</small></div></div><p class="ctf-flight-meta">小鱼航空 · '+f.no+'｜'+(f.large?'大型客机':'中型客机')+'｜'+cname(q.cls)+'</p><div class="ctf-flight-tags"><span>'+counts(q)+'</span><span>'+(f.bag?'含模拟托运行李':'仅随身行李')+'</span>'+(f.shared?'<span>模拟共享航班</span>':'')+'</div><div class="ctf-flight-actions"><small>成人单价 '+money(f.adultCents/100)+'</small><button class="ctf-book" data-flight="'+esc(f.id)+'" onclick="NorthFlightBooking.book(this.dataset.flight)" '+(o||expired?'disabled':'')+'>'+(expired?'已起飞':o?'已订':'订')+'</button>'+(o&&!expired?'<button class="ctf-refund" data-order="'+esc(o.id)+'" onclick="NorthFlightBooking.refund(this.dataset.order)">退</button>':'')+'</div></article>';}
function render(){if(detailId)return detailPage();const q=quote();if(orderView)return '<div class="ctf-app ctf-list-app"><header class="ctf-results-head"><button aria-label="返回机票查询" onclick="NorthFlightBooking.backToQuery()">‹</button><b>我的机票订单</b></header><div class="ctf-flight-policy">退款后24小时、出行日期结束后自动隐藏（跨日航班至抵达），账单保留。</div><main class="ctf-flight-scroll travel-scroll">'+(userRows().length?userRows().slice().reverse().slice(0,orderLimit).map(o=>'<section class="ctf-order-row">'+card(o)+'</section>').join('')+(userRows().length>orderLimit?'<button class="ctf-load-orders" onclick="NorthFlightBooking.moreOrders()">查看更多订单</button>':''):'<p class="ctf-flight-empty">暂无有效的机票订单</p>')+'</main></div>';if(!q||q.account!==account())return '';const l=q.legs[q.selectedLeg||0],a=sorted(q);return '<div class="ctf-app ctf-list-app"><header class="ctf-flight-header"><button aria-label="返回机票查询" onclick="NorthFlightBooking.backToQuery()">‹</button><button class="ctf-route-edit" onclick="NorthTravelFlight.edit()">'+esc(l.from)+' <i>→</i> '+esc(l.to)+'⌄</button><button class="ctf-my-orders" onclick="NorthFlightBooking.orders()">订单</button></header>'+(q.legs.length>1?'<nav class="ctf-leg-tabs">'+q.legs.map((l,i)=>'<button class="'+((q.selectedLeg||0)===i?'selected':'')+'" onclick="NorthFlightBooking.setLeg('+i+')">第'+(i+1)+'程 '+esc(l.from)+'→'+esc(l.to)+'</button>').join('')+'</nav>':'')+'<div class="ctf-date-strip">'+dateButtons(q)+'<button class="ctf-calendar" onclick="NorthFlightBooking.datePicker()">'+NorthTravelHome.icon('calendar')+'</button></div><div class="ctf-party-summary">'+esc(names(q))+' · '+counts(q)+'</div><nav class="ctf-sort">'+[['recommended','推荐排序'],['direct','直飞优先'],['time','时间排序'],['price','价格排序']].map(([k,n])=>'<button class="'+(q.sort===k?'selected':'')+'" onclick="NorthFlightBooking.sort(\''+k+'\')">'+n+'</button>').join('')+'<button onclick="NorthFlightBooking.filter()">筛选⌄</button></nav><nav class="ctf-quick-filters">'+[['afternoon','下午出发'],['large','大机型'],['bag','免费托运行李'],['noShared','隐藏共享航班']].map(([k,n])=>'<button class="'+(q.filters?.[k]?'selected':'')+'" onclick="NorthFlightBooking.toggle(\''+k+'\')">'+n+'</button>').join('')+'</nav><main class="ctf-flight-scroll travel-scroll">'+(a.length?a.map(f=>flightRow(q,f)).join(''):'<div class="ctf-flight-empty">没有符合筛选条件的模拟航班<button onclick="NorthFlightBooking.clearFilter()">清除筛选</button></div>')+'<p class="ctf-flight-policy">模拟航班与票价。儿童为成人价50%，婴儿为10%；往返、多程需逐程预订，按钮价格是这一程整组乘客总价。</p></main></div>';}
function moreOrders(){orderLimit+=12;redraw();}
function checkDue(){let changed=false;for(const o of rows()){if(o.status!=='upcoming'||o._reminded||o.date!==todayStr())continue;o._reminded=true;changed=true;for(const id of o.knownRoleIds||[]){const c=getC(id);if(c&&!c.deleted&&!c.blocked&&typeof scheduleReply==='function')scheduleReply(id,'[系统：今天是你知情的模拟机票出行日，'+summary(o)+'。按人设自然提醒出行和时间，只使用这里的真实同行信息，不要捏造机场或抵达情况。]');}}if(changed)save();const signature=account()+'|'+rows().map(o=>o.id+':'+o.status).join('|'),refresh=signature!==liveSignature;liveSignature=signature;if(refresh&&(typeof NorthTravelFlight!=='undefined'&&typeof NorthTravelFlight.active==='function'&&NorthTravelFlight.active()||typeof cur==='function'&&cur().p==='chat'))root.render();return changed;}
function backToQuery(){detailId=null;orderView=false;NorthTravelFlight.edit();}
function rolePrompt(c){const mine=rows().filter(o=>(o.knownRoleIds||[]).includes(c.id)),q=quote(),shared=q?.account===account()&&Array.isArray(q.people)&&q.people.some(p=>p.id==='role:'+c.id);return '\n\n# 新版模拟机票订单\n'+(mine.length?mine.map(summary).join('\n'):'暂无你参与或付款的机票订单。')+'\n'+NorthHotelData.roleAdvice()+'\n需要你实际付款订票时，单独输出 [订机票|出发城市|到达城市|YYYY-MM-DD|经济舱/公务舱/头等舱|我们一起/给你/我自己]。只使用你自己的银行余额，不用用户钱包或亲属卡，失败不得说订好；这是模拟预订。'+(shared?'\n用户当前机票查询（仅查询，尚未购买）：'+JSON.stringify({cls:q.cls,legs:q.legs,people:q.people,adults:q.adults,children:q.children,infants:q.infants})+'。明确要按这次查询订某一程时可输出 [订机票查询|第几程]（从1开始），系统选该程最低价且尚未起飞的模拟航班。':'');}
function roleDirect(c,from,to,date,cls,guest){if(!c||!flightReady())return false;const data=NorthHotelData,s=NorthTravelFlight.state(),l=s.legs?.[0]||{};guest=data.roleGuest(guest);from=data.roleCity(from,l.from||'北京');to=data.roleCity(to,l.to||'上海');if(data.normalize(from)===data.normalize(to)&&data.roleEmpty(arguments[2]))to=from==='上海'?'北京':'上海';date=data.roleDate(date,c);const k={经济舱:'economy',公务舱:'business',商务舱:'business',头等舱:'first'}[cls]||'economy';const q={account:account(),type:'one',cls:k,adults:guest==='我们一起'?2:1,children:0,infants:0,people:guest==='我自己'?[{id:'role:'+c.id,name:c.remark||c.name}]:guest==='给你'?[{id:'me',name:S.me.name}]:[{id:'me',name:S.me.name},{id:'role:'+c.id,name:c.remark||c.name}],legs:[{from,to,date}],selectedLeg:0,id:uidSafe()};const f=flights(q).filter(x=>x.departAt>Date.now()).sort((a,b)=>a.totalCents-b.totalCents)[0];return !!f&&bookQuote(q,f.id,c);}
function roleQuery(c,leg){const q=quote(),i=Number(leg)-1;if(!c||!Number.isInteger(i)||!q||q.account!==account()||!q.legs[i]||!q.people.some(p=>p.id==='role:'+c.id))return false;const copy={...q,selectedLeg:i},f=flights(copy).filter(x=>x.departAt>Date.now()).sort((a,b)=>a.totalCents-b.totalCents)[0];return !!f&&bookQuote(copy,f.id,c);}
function consume(content,c,done){let failed=false;content=String(content||'').replace(/\[订机票\|([^\]\n]+)\]/g,(_,args)=>{const a=args.split('|'),ok=a.length>=1&&a.length<=5&&roleDirect(c,...a.map(x=>x.trim()));failed=failed||!ok;done(!!ok);return '';}).replace(/\[订机票查询\|([^\]\n]+)\]/g,(_,i)=>{const ok=roleQuery(c,i.trim());failed=failed||!ok;done(ok);return '';});return failed?'':content;}
function inspection(){return rows().slice(-24).map(summary).join('\n');}
root.NorthFlightBooking={startQuote,render,rows,userRows,deadline,visible,current,summary,card,detail,detailBack,book,refund,bookQuote,flights,total,validate,sort,toggle,filter,saveFilter,clearFilter,setLeg,shiftDate,datePicker,useDate,orders,backToQuery,moreOrders,checkDue,rolePrompt,roleDirect,roleQuery,consume,inspection};
})(globalThis);
